<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api} from '../api'
import {money,number,percent,price,time} from '../format'
import {preferredPlatform,reportExpired,currentEvidenceVersion} from '../tokenCheck'
import type {TokenCandidate,TokenReport,TokenRecent,TokenFollowup} from '../tokenCheck'
import {recentTokenQueriesKey,parseRecentTokenQueries,rememberTokenQuery} from '../recentTokenQueries'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
import TokenSecurity from '../components/TokenSecurity.vue'
import TokenResearch from '../components/TokenResearch.vue'
import TokenMonitor from '../components/TokenMonitor.vue'
const followup=ref<TokenFollowup|null>(null);const followupError=ref('');
async function loadFollowup(id:string){followup.value=null;followupError.value='';try{const value=await api<TokenFollowup>(`/api/token-check/${id}/followup`);if(report.value?.id===id)followup.value=value}catch{if(report.value?.id===id)followupError.value='本地跟踪记录暂不可读，原始报告不受影响。'}}
const query=ref('');const candidates=ref<TokenCandidate[]>([]);const selected=ref<TokenCandidate|null>(null);const platform=ref('');const assetId=ref('');
const report=ref<TokenReport|null>(null);const recent=ref<TokenRecent[]>([]);const error=ref('');const searching=ref(false);const analyzing=ref(false);const searched=ref(false);const now=ref(Date.now());
const recentQueries=ref<string[]>([]),cacheNotice=ref('');let seedRecentQueries=true;
function saveQueries(){try{localStorage.setItem(recentTokenQueriesKey,JSON.stringify({version:1,queries:recentQueries.value}));cacheNotice.value=''}catch{cacheNotice.value='浏览器暂不能保存记录，本次仍可查询；离开页面后可能无法保留。'}}
function remember(query:string){recentQueries.value=rememberTokenQuery(recentQueries.value,query);seedRecentQueries=false;saveQueries()}
function removeQuery(query:string){recentQueries.value=recentQueries.value.filter(q=>q!==query);seedRecentQueries=false;saveQueries()}
function clearQueries(){recentQueries.value=[];seedRecentQueries=false;saveQueries()}
const busy=computed(()=>searching.value||analyzing.value);const address=computed(()=>selected.value?.coin.platforms[platform.value]??'');
const expired=computed(()=>report.value?reportExpired(report.value.expiresAt,now.value):false);
const route=useRoute();const router=useRouter();
const displayCandidates=computed(()=>candidates.value.some(c=>c.exactMatch)?candidates.value.filter(c=>c.exactMatch):candidates.value);
let searchAbort:AbortController|undefined;let reportAbort:AbortController|undefined;let clock:ReturnType<typeof setInterval>|undefined;
async function history(){recent.value=await api<TokenRecent[]>('/api/token-check/recent');if(seedRecentQueries){recentQueries.value=recent.value.reduceRight<string[]>((queries,r)=>rememberTokenQuery(queries,r.coin.name),[]);seedRecentQueries=false;saveQueries()}}
async function search(value?:string){if(analyzing.value)return;if(value)query.value=value;const term=query.value.trim();if(term.length<2||term.length>100)return;searchAbort?.abort();searchAbort=new AbortController();const current=searchAbort;searching.value=true;error.value='';selected.value=null;report.value=null;candidates.value=[];searched.value=false;if(route.query.report)void router.replace({query:{}});
try{const rows=await api<TokenCandidate[]>(`/api/token-check/search?q=${encodeURIComponent(term)}`,{signal:current.signal});if(!current.signal.aborted){candidates.value=rows;searched.value=true;if(rows.length)remember(term)}}
catch(e){if(!current.signal.aborted)error.value=String(e)}finally{if(searchAbort===current)searching.value=false}}
function choose(c:TokenCandidate){if(busy.value)return;selected.value=c;platform.value=preferredPlatform(c.coin.platforms);assetId.value=c.instruments.length===1?String(c.instruments[0]!.assetId):'';report.value=null;error.value=''}
async function analyze(){if(busy.value||!selected.value||!address.value)return;analyzing.value=true;error.value='';report.value=null;reportAbort=new AbortController();
try{report.value=await api<TokenReport>('/api/token-check',{method:'POST',signal:reportAbort.signal,headers:{'Content-Type':'application/json'},body:JSON.stringify({coinGeckoId:selected.value.coin.id,platform:platform.value,contractAddress:address.value,assetId:assetId.value?Number(assetId.value):null})});now.value=Date.now();await router.replace({query:{report:report.value.id}});await Promise.all([history(),loadFollowup(report.value.id)])}
catch(e){error.value=e instanceof Error?e.message:String(e)}finally{analyzing.value=false}}
async function open(id:string){if(busy.value)return;analyzing.value=true;error.value='';selected.value=null;report.value=null;
try{report.value=await api<TokenReport>(`/api/token-check/${id}`);now.value=Date.now();await router.replace({query:{report:report.value.id}});await loadFollowup(report.value.id)}catch(e){error.value=String(e)}finally{analyzing.value=false}}
onMounted(()=>{clock=setInterval(()=>now.value=Date.now(),1000);try{const saved=parseRecentTokenQueries(localStorage.getItem(recentTokenQueriesKey));if(saved!==null){recentQueries.value=saved;seedRecentQueries=false}}catch{cacheNotice.value='浏览器暂不能读取最近查询，仍可正常查找代币。'}history().catch(e=>error.value=String(e));const id=route.query.report;if(typeof id==='string'&&/^[0-9a-f-]{36}$/i.test(id))void open(id)});onUnmounted(()=>{searchAbort?.abort();reportAbort?.abort();clearInterval(clock)})
</script>
<template>
<PageIntro eyebrow="TOKEN QUICK CHECK · ON DEMAND" title="看到一个币，先查清再判断。" description="独立快速辅助：当前是否适合参与、潜力依据、风险与缺失分开说明。输入名称、代码或完整合约/Mint。"><RouterLink to="/opportunities">查看妖币与榜单探测 →</RouterLink></PageIntro>
<form class="market-panel" @submit.prevent="search()"><div class="toolbar"><label class="search"><input v-model="query" aria-label="输入代币名称或代码" placeholder="输入名称、代码或完整合约 / Mint" minlength="2" maxlength="100" :disabled="analyzing"></label><button class="replay-action" :disabled="busy||query.trim().length<2">{{searching?'搜索中…':'查找代币'}}</button></div><div class="recent-queries" aria-label="最近查询"><span class="refresh-text">最近查询</span><template v-if="recentQueries.length"><div class="query-chips"><span v-for="q in recentQueries" :key="q" class="query-chip"><button type="button" class="query-repeat" :title="q" :aria-label="`重新查找 ${q}`" :disabled="busy" @click="search(q)">{{q}}</button><button type="button" class="query-remove" :aria-label="`删除最近查询 ${q}`" :title="`删除 ${q}`" @click="removeQuery(q)">×</button></span></div><button type="button" class="text-button query-clear" @click="clearQueries">清空</button></template><span v-else class="refresh-text">还没有记录，查找后会保留最近5个关键词。</span><p class="refresh-text query-help">仅保存在本机浏览器；点击重新查找，再选择代币生成最新报告。同名不自动选币。</p><p v-if="cacheNotice" role="status" class="refresh-text query-help">{{cacheNotice}}</p></div></form>
<p v-if="error" role="alert" class="radar-notice">{{error}}</p>
<TokenMonitor/>
<p v-if="searched&&!candidates.length" class="radar-notice">当前目录没有匹配项。请核对拼写、完整项目名称或链合约；不会将 AOI 自动改成 AIO，也不会从同名中挑市值最高的币。</p>
<section v-if="candidates.length" class="detail"><h2>先确认你看到的是哪一个币</h2><p v-if="displayCandidates.length<candidates.length" class="refresh-text">优先展示名称/代码精确匹配的 {{displayCandidates.length}} 个候选；其余 {{candidates.length-displayCandidates.length}} 个仅为部分匹配，可输入更完整名称缩小搜索。</p><div class="candidate-grid"><button v-for="c in displayCandidates" :key="c.coin.id" type="button" class="candidate" :class="{selected:selected?.coin.id===c.coin.id}" :disabled="busy" @click="choose(c)"><b>{{c.coin.name}} · {{c.coin.symbol.toUpperCase()}}</b><span>ID · {{c.coin.id}}</span><span>{{c.exactMatch?'名称或代码精确匹配':'部分匹配，仅作搜索线索'}} · {{c.instruments.map(i=>i.symbol).join(' / ')||'本地无同代码永续'}}</span><small v-for="(a,p) in c.coin.platforms" :key="p">{{p}} · {{a}}</small><small v-if="!Object.keys(c.coin.platforms).length">目录暂无合约，暂不能完成本版本身份快查</small></button></div></section>
<section v-if="selected" class="detail"><h2>{{selected.coin.name}} · 选择分析身份</h2><p>CoinGecko ID · {{selected.coin.id}}。同代码交易对只是候选；必须通过完整链合约交叉核验后才会关联报价。</p><div class="mapping-form"><label>链<select v-model="platform" aria-label="选择快查链" :disabled="busy"><option v-for="(_,p) in selected.coin.platforms" :key="p" :value="p">{{p}}</option></select></label><label>候选交易对<select v-model="assetId" aria-label="选择快查交易对" :disabled="busy"><option value="">仅项目与链上资料</option><option v-for="i in selected.instruments" :key="i.assetId" :value="String(i.assetId)">{{i.symbol}} · 核验后关联</option></select></label></div><p class="contract">完整合约 / Mint · {{address||'缺失'}}</p><button class="replay-action" :disabled="busy||!address" @click="analyze">{{analyzing?'正在核验并生成报告…':'分析这个代币'}}</button><p class="refresh-text">通常需数十秒；资料失败也会说明。报告原样留档，1分钟内重复分析复用原报告。外部请求计入现有流量预算，链上沿用共享额度/冷却。</p></section>
<p v-if="analyzing" class="radar-notice" role="status">正在处理，请稍候。快查不增加自选、不加入妖币池，也不执行模拟或真实下单。</p>
<template v-if="report"><section class="detail report-top"><div class="section-heading"><h2>{{report.coin.name}} · {{report.coin.symbol.toUpperCase()}}</h2><strong>{{expired?'报告已过参考期':report.verdict}}</strong></div><p>{{report.platform}} · <span class="contract">{{report.contractAddress}}</span></p><p>生成 {{time(report.asOf)}} · 短线参考截止 {{time(report.expiresAt)}} · {{report.version}}</p><p v-if="expired" class="radar-notice">这份是历史快照，当前行情可能已经变化。重新选择该项目生成新报告，再判断参与条件。</p><h3>现在是否适合参与</h3><p>{{report.verdict}} · {{report.summary}}</p><h3>潜力怎么看</h3><p>{{report.potential}}</p><p>{{report.identityVerified?'身份交叉核验通过':'身份尚未核验'}} · {{report.identityReason}}</p><p class="refresh-text">{{report.isolation}}</p></section>
<div class="stats"><StatCard label="证据完整度" :value="`${report.evidenceCoverage}%`" :foot="report.evidenceMeaning"/><StatCard label="参考价格" :value="price(report.price)" :foot="report.instrument?'身份关联的永续报价优先；失鲜时仅项目USD资料':'项目USD聚合报价'"/><StatCard label="流通市值 / FDV" :value="money(report.project?.marketCapUsd)" :foot="`FDV ${money(report.project?.fdvUsd)} · 来源 ${time(report.project?.sourceTime)}`"/><StatCard label="当前结构" :value="report.technical.trend" :foot="`${report.technical.hours}根闭合小时线 · ${report.technical.continuous?'连续性通过':'历史不足或有缺口'}`"/></div>
<div class="evidence-grid"><section class="detail"><h2>支持依据</h2><p v-for="s in report.supporting" :key="s">{{s}}</p><p v-if="!report.supporting.length">暂缺可用支持证据。</p></section><section class="detail"><h2>风险与反证</h2><p v-for="s in report.risks" :key="s">{{s}}</p><p v-if="!report.risks.length">当前已取到的字段未形成明确反证，仍需检查下方缺失项。</p></section></div>
<section class="detail"><h2>关键位置与参与条件 · 小时结构</h2><p>近24小时闭合价变化 {{percent(report.technical.return24h)}} · EMA20 {{price(report.technical.ema20)}} / EMA60 {{price(report.technical.ema60)}} · ATR14 {{price(report.technical.atr14)}}</p><div class="detail-grid"><div><span>最近已确认支撑</span><strong>{{price(report.technical.support)}}</strong><small>{{time(report.technical.supportTime)}}</small></div><div><span>上方已确认压力</span><strong>{{price(report.technical.resistance)}}</strong><small>{{time(report.technical.resistanceTime)}}</small></div><div><span>结构失效参考（支撑下0.5ATR）</span><strong>{{price(report.technical.invalidation)}}</strong></div><div><span>至压力的结构收益风险比</span><strong>{{number(report.technical.rewardRiskToResistance)}} R</strong></div></div><p v-for="s in report.nextChecks" :key="s">{{s}}</p><p class="refresh-text">支撑/压力采用右侧两根已闭合小时K线确认的拐点。它们不是委托价；未计手续费/滑点，不给未知压力编造止盈目标，也不套用模拟账户的10倍杠杆。</p></section>
<section class="detail"><h2>资金、估值与供应</h2><p>永续24h报价成交额 {{money(report.perpetualVolume24h)}} · 项目现货聚合24h成交额 {{money(report.project?.spotVolume24hUsd)}}，两者不混算。</p><p>OI数量24h变化 {{percent(report.oi24hPercent)}} · OI源时间 {{time(report.oiSourceTime)}} · 本次资金费率 {{report.fundingRate==null?'Unknown':percent(report.fundingRate*100)}}（结算频率需另核对）</p><p>流通供应 {{number(report.project?.circulatingSupply,0)}} · 总供应 {{number(report.project?.totalSupply,0)}}。流通比例不等于即将解锁比例。</p><p v-for="url in report.project?.websites??[]" :key="url"><a :href="url" target="_blank" rel="noopener noreferrer">项目资料入口 · {{url}} ↗</a></p></section>
<TokenSecurity :evidence="report.chainSample?.security" :now="now" :allow-review="false"/>
<TokenResearch :holders="report.holderAnalysis" :research="report.research" :followup="followup" :followup-error="followupError"/>
<section class="detail"><h2>缺失证据与待核验</h2><p v-for="s in report.missing" :key="s">{{s}}</p></section>
<section class="detail"><h2>来源与时效 · 报告 {{report.id}}</h2><div class="table-scroll"><table><thead><tr><th>来源 / 状态</th><th>原始时间 / 接收</th><th>口径</th></tr></thead><tbody><tr v-for="(s,i) in report.sources" :key="i"><td><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.name}} ↗</a><small>{{s.status}}</small></td><td>{{time(s.sourceTime)}}<small>{{time(s.receivedTime)}}</small></td><td>{{s.note}}</td></tr></tbody></table></div></section></template>
<section class="detail"><h2>最近快查 · 独立报告留档</h2><p v-if="!recent.length">还没有快查报告。生成后保留当时的判断、来源和缺失项，方便回头复盘。</p><div class="table-scroll" v-else><table><thead><tr><th>项目 / 链</th><th>时间</th><th>当时判断</th><th>操作</th></tr></thead><tbody><tr v-for="r in recent" :key="r.id"><td>{{r.coin.name}} · {{r.coin.symbol.toUpperCase()}}<small>{{r.platform}} · {{r.coin.id}}</small></td><td>{{time(r.asOf)}}<small>{{reportExpired(r.expiresAt,now)?'历史快照':'参考期内'}}</small></td><td>{{r.verdict}} · {{currentEvidenceVersion(r.version)?`完整度${r.evidenceCoverage}%`:'旧版市场字段口径'}}</td><td><button class="text-button" :disabled="busy" @click="open(r.id)">查看报告</button></td></tr></tbody></table></div></section>
</template>
<style scoped>.recent-queries{display:flex;align-items:center;flex-wrap:wrap;gap:10px;padding:16px 20px;border-top:1px solid #26343e}.query-chips{display:flex;flex-wrap:wrap;gap:8px;min-width:0}.query-chip{display:inline-flex;align-items:center;max-width:100%;border:1px solid #304b46;background:#132521;border-radius:6px;overflow:hidden}.query-repeat,.query-remove{border:0;background:transparent;color:#9edaca;cursor:pointer;min-height:34px}.query-repeat{max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding:6px 10px;font-size:12px}.query-remove{border-left:1px solid #304b46;padding:6px 10px;font-size:17px;line-height:1}.query-repeat:hover,.query-remove:hover{background:#1d3a31;color:#d9f6eb}.query-repeat:focus-visible,.query-remove:focus-visible{outline:2px solid #66d6b0;outline-offset:-2px}.query-repeat:disabled{opacity:.5;cursor:wait}.query-clear{margin-left:auto}.query-help{flex-basis:100%;margin:0;line-height:1.8}.candidate-grid,.evidence-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.candidate{text-align:left;display:grid;gap:9px;background:#111a22;border:1px solid #31404b;color:inherit;border-radius:8px;padding:18px;cursor:pointer;overflow-wrap:anywhere}.candidate.selected{border-color:#5bd9ae;background:#17322b}.candidate span,.candidate small{font-size:12px;color:#9aaebe}.candidate b{font-size:15px}.contract,.detail p,.detail a{overflow-wrap:anywhere}.report-top{border-color:#3a6557}:deep(.stat:last-child strong){font-size:20px;line-height:1.5}.detail small{display:block;color:#9aaebe;font-size:11px;margin-top:6px}.evidence-grid .detail{margin-top:0}@media(max-width:760px){.candidate-grid,.evidence-grid{grid-template-columns:1fr}}</style>
